// CMS documents in Supabase.
//
// One table, `cms_documents`, keyed by the same path the rest of this project
// already uses:
//
//   applications/applications.json   the application forms
//   properties/properties.json       every property
//
// That is not a coincidence. MTC-KRP-031 defined the backend contract as
// `POST /api/save-json { path, content }`, and this is that contract with a
// Postgres row where the worker would have been. The path allow-list, the
// document shapes and the guarantees the browser makes before sending are all
// unchanged — which is why moving to Supabase is an adapter, not a rewrite.
//
// Reads are public. A property page has to render for somebody who is not
// signed in, so the row is readable by anyone and Row Level Security allows
// only authenticated users to write. See supabase/schema.sql.

import { ALLOWED_PATHS } from "../../contracts/saveJson.ts";
import { supabaseRequest } from "./client.ts";
import type { SupabaseResult } from "./client";

const TABLE = "/rest/v1/cms_documents";

export type CmsDocumentRow<T> = {
  path: string;
  content: T;
  updated_at?: string;
};

/**
 * Refuses a path the contract does not allow.
 *
 * The database enforces this too, with a CHECK constraint. This copy exists so
 * a mistake fails here with a sentence somebody can read, rather than as a
 * Postgres constraint violation — it is a convenience, NOT the security
 * boundary. The boundary is in the schema.
 */
function allowed(path: string): boolean {
  return (ALLOWED_PATHS as readonly string[]).includes(path);
}

/**
 * Reads one document.
 *
 * A missing row is `null`, not an error, and that distinction matters: before
 * the first save there IS no row, and the CMS is supposed to fall back to its
 * bundled starting point rather than show a failure.
 */
export async function loadDocument<T>(
  path: string
): Promise<SupabaseResult<T | null>> {
  const query = `${TABLE}?path=eq.${encodeURIComponent(path)}&select=content`;

  const result = await supabaseRequest<CmsDocumentRow<T>[]>(query, {
    method: "GET",
    /* Public. The website itself reads properties, and it has no session. */
    authenticated: false,
  });

  if (!result.ok) return result;

  const row = Array.isArray(result.data) ? result.data[0] : null;
  return { ok: true, data: row ? row.content : null };
}

/**
 * Writes one document, creating it if it does not exist.
 *
 * `Prefer: resolution=merge-duplicates` makes this an upsert on the primary
 * key, so the first save and the hundredth take the same path — no "does it
 * exist yet" branch to get wrong.
 */
export async function saveDocument<T>(
  path: string,
  content: T
): Promise<SupabaseResult<null>> {
  if (!allowed(path)) {
    return {
      ok: false,
      error: {
        status: 400,
        message: "That is not somewhere this site is allowed to save.",
      },
    };
  }

  const result = await supabaseRequest<unknown>(TABLE, {
    method: "POST",
    headers: {
      Prefer: "resolution=merge-duplicates,return=minimal",
    },
    body: [{ path, content }],
  });

  if (!result.ok) return result;
  return { ok: true, data: null };
}
