/* Explicit extension: this is the one runtime import in the modules the unit
   tests reach, and Node's type stripping resolves relative specifiers as ESM,
   which requires it. Webpack resolves it identically. */
import { makeId } from "./applicationRules.ts";
import type { GFormField } from "../gh-leads/GForm";
import type { ApplicationQuestion } from "./types";

/**
 * The application a site starts with.
 *
 * These are the same questions the public /apply page asks today (see
 * primitives/application/application-x), lifted so the Builder opens on the
 * form that is actually live rather than a blank screen. Once an editor saves,
 * the stored document is the source of truth and this is only ever the seed.
 */
export function defaultQuestions(now: number): ApplicationQuestion[] {
  /* Takes GFormField rather than Omit<ApplicationQuestion, "id">: GFormField
     carries an index signature, and Omit over one collapses the whole type to
     [x: string]: unknown, losing the required `name`. The id is added here so
     callers only write content. */
  const q = (field: GFormField): ApplicationQuestion => ({
    ...field,
    id: makeId("q", now),
  });

  return [
    q({
      name: "fullName",
      type: "text",
      label: "Full Name",
      placeholder: "Your full name",
      required: true,
    }),
    q({
      name: "email",
      type: "email",
      label: "Email Address",
      placeholder: "you@example.com",
      required: true,
    }),
    q({
      name: "phone",
      type: "tel",
      label: "Phone Number",
      placeholder: "(208) 000-0000",
      required: true,
    }),
    q({
      name: "property",
      type: "select",
      label: "Property of Interest",
      placeholder: "Select a property",
      options: [
        { label: "Oakwood Apartments", value: "oakwood-apartments" },
        { label: "Bristol Court", value: "bristol-court" },
        { label: "Warm Springs Townhomes", value: "warm-springs-townhomes" },
        { label: "Linden Studios", value: "linden-studios" },
        { label: "Maple Ridge", value: "maple-ridge" },
        { label: "Not sure yet", value: "undecided" },
      ],
    }),
    q({
      name: "homeType",
      type: "select",
      label: "Home Size",
      placeholder: "Select a size",
      required: true,
      options: [
        { label: "Studio", value: "studio" },
        { label: "1 Bedroom", value: "1-bedroom" },
        { label: "2 Bedroom", value: "2-bedroom" },
        { label: "3 Bedroom", value: "3-bedroom" },
      ],
    }),
    q({
      name: "moveInDate",
      type: "date",
      label: "Preferred Move-In Date",
    }),
    q({
      name: "occupants",
      type: "text",
      label: "Number of Occupants",
      placeholder: "How many people will live in the home?",
    }),
    q({
      name: "pets",
      type: "radio",
      label: "Do You Have Pets?",
      options: [
        { label: "No pets", value: "none" },
        { label: "Yes, one", value: "one" },
        { label: "Yes, more than one", value: "several" },
      ],
    }),
    q({
      name: "message",
      type: "textarea",
      label: "Anything Else We Should Know?",
      placeholder: "Tell us anything that would help us help you.",
      rows: 5,
    }),
  ];
}
