// The Application Builder's data boundary.
//
// Read and write are deliberately asymmetric, which is the shape the rest of
// this CMS already uses (see gh-image/imageApi.ts):
//
//   read   public JSON over HTTP from the site's content repo — no auth, no
//          worker, cache-busted so an editor sees their own save
//   write  authenticated POST to the site's Cloudflare Worker, which holds the
//          GitHub token and commits the file
//
// The UI never learns any of that. It calls load() and save() and gets an
// ApplicationsDocument back, so moving the store later is a change to this file
// and nothing else.

import { GH_APPLY_REPO } from "../../config/gh-apply--repo.ts";
import demoLocalStorage from "../../toggles/demo-local-storage.ts";
import { usingSupabase } from "../supabase/enabled.ts";
import { supabaseApplicationsApi } from "../supabase/applicationsSupabase.ts";
import { localApplicationsApi, parseDocument, seedDocument } from "./applicationsStore.ts";
import type { ApplicationsApi, LoadResult, LoadSource } from "./applicationsStore.ts";

/* Re-exported so every existing importer keeps its import path. */
export { localApplicationsApi, seedDocument };
export type { ApplicationsApi, LoadResult, LoadSource };
import { GH_APPLY_WORKER } from "../../config/gh-apply--worker-url.ts";
import { getToken } from "../../config/opencms--useAuth.ts";
import { APPLICATIONS_DOC, checkApplicationsPath } from "./applicationsPath.ts";
import type { ApplicationsDocument } from "./types";

const DOCUMENT_URL = `${GH_APPLY_REPO}/${APPLICATIONS_DOC}`;
const SAVE_URL = `${GH_APPLY_WORKER}/api/save-json`;

/**
 * A save that failed because the site has no storage yet, as opposed to one
 * that failed for a reason the editor could act on.
 *
 * Flagged rather than matched on its message so callers can tell the two apart
 * without depending on wording. The walkthrough uses it to keep going in
 * practice mode; everything else still just reports the failure.
 */
export class StorageNotConnectedError extends Error {
  readonly notConnected = true;

  constructor(message: string) {
    super(message);
    this.name = "StorageNotConnectedError";
  }
}

export function isNotConnected(error: unknown): boolean {
  return (
    error instanceof StorageNotConnectedError ||
    (typeof error === "object" &&
      error !== null &&
      (error as { notConnected?: boolean }).notConnected === true)
  );
}

export const remoteApplicationsApi: ApplicationsApi = {
  async load(): Promise<LoadResult> {
    try {
      const res = await fetch(`${DOCUMENT_URL}?v=${Date.now()}`, {
        headers: { Accept: "application/json" },
      });

      if (res.ok) {
        const parsed = parseDocument(await res.json());
        if (parsed) return { doc: parsed, remote: true, source: "remote" };
      }
    } catch {
      // Offline, or the content repo does not exist yet. Either way the editor
      // gets a working screen; save() is what reports a broken backend.
    }

    return { doc: seedDocument(Date.now()), remote: false, source: "seed" };
  },

  async save(doc: ApplicationsDocument): Promise<void> {
    // Checked here so a bad path never leaves the browser. The Worker checks
    // again, because this check is a convenience and not a security boundary.
    const path = checkApplicationsPath(APPLICATIONS_DOC);
    if (!path.ok) {
      throw new Error(`Refusing to save: ${path.reason}`);
    }

    const token = getToken();
    if (!token) {
      throw new Error("You are signed out. Sign in again to save changes.");
    }

    let res: Response;

    try {
      res = await fetch(SAVE_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ path: APPLICATIONS_DOC, content: doc }),
      });
    } catch {
      throw new StorageNotConnectedError(
        "Could not reach the save service. Your changes have not been saved."
      );
    }

    const text = await res.text();

    if (!res.ok) {
      let json: { error?: string } | null = null;
      try {
        json = JSON.parse(text);
      } catch {
        // Not JSON — Cloudflare answers with plain text when a worker is
        // missing, which is exactly the case worth naming below.
      }

      if (res.status === 404) {
        throw new StorageNotConnectedError(
          "Saving is not connected yet. The site's content worker has not been " +
            "deployed, so there is nowhere to save to. Nothing was saved."
        );
      }

      throw new Error(
        json?.error ?? text ?? `Save failed (HTTP ${res.status}). Nothing was saved.`
      );
    }
  },
};

/**
 * The one the CMS uses.
 *
 * Swapped by toggles rather than by editing any component. Supabase wins when
 * the project is configured; otherwise this falls back exactly as before. See
 * modules/supabase/enabled.ts and toggles/demo-local-storage.ts.
 */
export const applicationsApi: ApplicationsApi = usingSupabase()
  ? supabaseApplicationsApi
  : demoLocalStorage
    ? localApplicationsApi
    : remoteApplicationsApi;
