// The Application Builder's document, and where a demo keeps it.
//
// Split from applicationsApi.ts so that the demo path depends on NOTHING but
// the rules and browser storage. The remote adapter reaches for a repo URL, a
// worker URL and an auth token; none of that has any business being loaded
// just to read a document out of localStorage, and keeping them apart is what
// lets this be tested without a network, a token or a build.

import { createApplication } from "./applicationRules.ts";
import { defaultQuestions } from "./defaultApplication.ts";
import type { ApplicationsDocument } from "./types";
import { STORAGE_KEYS, readJson, writeJson } from "../shared/localStore.ts";

/**
 * Where the document actually came from.
 *
 * Three states rather than a boolean, because "not from the repo" now covers
 * two very different situations: a demo saved in this browser, which the
 * editor's own work is in, and an untouched seed, which it is not.
 */
export type LoadSource = "remote" | "local" | "seed";

export type LoadResult = {
  doc: ApplicationsDocument;
  /**
   * True when the document came back from the repo, false when it does not
   * exist yet and this is the bundled starting point. The UI says which, so
   * nobody edits a default for an hour believing it was already published.
   */
  remote: boolean;
  source: LoadSource;
};

/**
 * A save that failed because the site has no storage yet, as opposed to one
 * that failed for a reason the editor could act on.
 *
 * Flagged rather than matched on its message so callers can tell the two apart
 * without depending on wording. The walkthrough uses it to keep going in
 * practice mode; everything else still just reports the failure.
 */
export class StorageNotConnectedError extends Error {
  readonly notConnected = true;

  constructor(message: string) {
    super(message);
    this.name = "StorageNotConnectedError";
  }
}

export function isNotConnected(error: unknown): boolean {
  return (
    error instanceof StorageNotConnectedError ||
    (typeof error === "object" &&
      error !== null &&
      (error as { notConnected?: boolean }).notConnected === true)
  );
}

export type ApplicationsApi = {
  load: () => Promise<LoadResult>;
  save: (doc: ApplicationsDocument) => Promise<void>;
};

/**
 * The document a site starts with.
 *
 * Seeded from the questions the public /apply page already asks, so the first
 * thing an editor sees in the Builder is the form that is actually live rather
 * than an empty screen.
 */
export function seedDocument(now: number): ApplicationsDocument {
  const empty: ApplicationsDocument = {
    version: 1,
    activeId: "",
    applications: [],
  };

  return createApplication(
    empty,
    "Standard Rental Application",
    now,
    defaultQuestions(now)
  ).doc;
}

/** Rejects anything that is not the document shape, rather than trusting it. */
export function parseDocument(value: unknown): ApplicationsDocument | null {
  if (!value || typeof value !== "object") return null;

  const doc = value as Partial<ApplicationsDocument>;

  if (typeof doc.activeId !== "string") return null;
  if (!Array.isArray(doc.applications)) return null;

  return {
    version: typeof doc.version === "number" ? doc.version : 1,
    activeId: doc.activeId,
    applications: doc.applications,
  };
}

/* ── demo persistence ─────────────────────────────────────
   The same interface, saving to this browser instead of to a worker that does
   not exist yet. Everything above it — ApplyView, the Builder, the Trash, the
   walkthrough — is unchanged and cannot tell which one it is holding.

   The seed is used ONLY when there is no valid saved document, so a demo
   survives a refresh instead of being overwritten by the starting application
   on every load. */
export const localApplicationsApi: ApplicationsApi = {
  async load(): Promise<LoadResult> {
    const saved = readJson(STORAGE_KEYS.applications, parseDocument);
    if (saved) return { doc: saved, remote: false, source: "local" };

    return { doc: seedDocument(Date.now()), remote: false, source: "seed" };
  },

  async save(doc: ApplicationsDocument): Promise<void> {
    const result = writeJson(STORAGE_KEYS.applications, doc);

    /* A real failure, thrown like any other. The point of demo mode is that a
       save either happens or is reported — never that it always appears to. */
    if (!result.ok) throw new Error(result.reason);
  },
};

