// GET <contentRepo>/properties/properties.json
//
// Every property on the site. No auth; a 404 is fine before the first save,
// because twelve sample properties ship in source.
//
// The record here is the SAME object the public website renders. There is no
// editing model, no transfer model and no separate public model to keep in
// step — what the CMS saves is what the property page reads.

import type { PropertyRecord } from "./models";

export const METHOD = "GET" as const;
export const PATH = "properties/properties.json";
export const AUTH = "none" as const;

export type GetPropertiesRequest = void;

export type GetPropertiesResponse = {
  /** 1 today. Bumped only for a breaking shape change. */
  version: number;
  properties: PropertyRecord[];
};

/** Alias used by the write side too. */
export type PropertiesDocument = GetPropertiesResponse;

/**
 * The one rule worth enforcing here:
 *
 * `publication` alone decides whether a property is on the website. NEVER
 * infer it from `availability`. A published property saying "Contact for
 * Availability" is an ordinary listing with a waiting list; a draft saying
 * "Available Now" is simply unfinished.
 */
export const PUBLICATION_STATES = ["draft", "published"] as const;
